def convertir_datos(apps, schema_editor):
    """Ajusta los datos que ya existan a las nuevas reglas."""
    Cliente = apps.get_model("gmf", "Cliente")
    ProgresoFisico = apps.get_model("gmf", "ProgresoFisico")
    Alimento = apps.get_model("gmf", "Alimento")
    RutinaEjercicio = apps.get_model("gmf", "RutinaEjercicio")

    # Altura: de metros (1.75) a centímetros (175.0)
    for modelo in (Cliente, ProgresoFisico):
        for obj in modelo.objects.exclude(altura=None):
            if obj.altura < 3:
                obj.altura = obj.altura * 100
                obj.save(update_fields=["altura"])

    # Alimentos: los valores pasan a ser por cada 100 g
    for al in Alimento.objects.exclude(porcion_gramos=100):
        factor = Decimal(100) / al.porcion_gramos
        for campo in ("kcal", "proteinas", "carbohidratos", "grasas"):
            setattr(al, campo, (getattr(al, campo) * factor).quantize(Decimal("0.01")))
        al.save()

    # Repeticiones: el valor anterior pasa a repeticiones_min (tipo "reps máximas")
    for re in RutinaEjercicio.objects.all():
        re.repeticiones_min = re.repeticiones
        re.tipo_repeticiones = "MAXIMAS"
        re.save()


